Lemma amb_seg1 : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (b first lo : Z) (wprev : word),
  a0 = wz b ->
  rw_cells asegs m (b + 8) [C8 (wz first); C8 wprev] -> 0 <= first < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> aceil <= lo ->
  aapp b 64 -> b mod 8 = 0 -> accessible m b 64 ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (amb_seg1_post ra sp gp tp a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc t0 t1 t2 t3 t4 t5 t6 s0 s1 b first lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (wz P_A_MB_DTOR) fc None m (seg_rom asegs)).
