(* [comment removed for export] *)
Definition amb_rem (m : mem) (LBc : list block) (hL : Z) (bs : list block) (es : list mbe) : Prop :=
  forall A b B, bs = A ++ b :: B ->
    In b LBc /\ exists sz (wprev : word) junk, In (blk_addr b, sz) es /\ blk_size b = mb_block_size sz
      /\ rw_cells asegs m (blk_addr b) [C8 (wz (lhead hL (map blk_addr B))); C8 wprev]
      /\ rw_cells asegs m (blk_addr b + 16) [C8 (wz sz); CB (Z.to_nat (mb_block_size sz - 24)) junk]
      /\ addressable m (blk_addr b) (mb_block_size sz).

(* [comment removed for export] *)
Lemma mbe_blob : forall m x nxt (wprev : word) sz junk,
  0 <= sz ->
  rw_cells asegs m x [C8 (wz nxt); C8 wprev] -> rw_cells asegs m (x + 16) [C8 (wz sz); CB (Z.to_nat (mb_block_size sz - 24)) junk] ->
  exists bs, rw_cells asegs m x [CB (Z.to_nat (mb_block_size sz)) bs].
Proof.
  intros m x nxt wprev sz junk S0 LN PL. pose proof (mb_block_size_range sz S0) as [[R1 R2] R8].
  assert (C : rw_cells asegs m x ([C8 (wz nxt); C8 wprev] ++ [C8 (wz sz); CB (Z.to_nat (mb_block_size sz - 24)) junk])).
  { apply rw_cells_app. split; [exact LN|]. cbn [cells_size csize Nat.add]. replace (x + Z.of_nat 16) with (x + 16) by lia. exact PL. }
  destruct (rw_cells_forget _ _ _ _ C) as [bb K]. exists bb.
  cbn [cells_size csize Nat.add app] in K.
  replace (Z.to_nat (mb_block_size sz)) with (8 + (8 + (8 + (Z.to_nat (mb_block_size sz - 24) + 0))))%nat by lia. exact K.
Qed.

